", E "check-library.lua": "return rule('demo.lib.check', {'actor','skill'}, function(r, actor, skill)
 r.ownedSkill(actor, skill)
 local target = r.number(skill, 'value')
 local rolled = r.roll(100)
 return {target=target, rolled=rolled, passed=rolled<=target}
end, {public=false})
", E "damage-library.lua": "return rule('demo.lib.damage', {'actor','amount'}, function(r, actor, amount)
 local lost = math.max(0, amount-r.number(actor,'armor'))
 r.set(actor, 'hp', math.max(0,r.number(actor,'hp')-lost))
end, {public=false})
", E "damage.lua": "return rule('demo.damage', {'actor','amount'}, function(r, actor, amount)
 r.damage(actor, amount)
end)
", E "environment.lua": "return rule('demo.environment', {'actor'}, function(r, actor)
 return r.number(actor,'attack') + r.readData('environment.json').attackBonus
end, {mode='calculation'})
", E "rules.lua": "return rule('demo.check', {'actor','skill'}, function(r, actor, skill)
 return r.check(actor, skill).passed
end)
", E "ruling.lua": "return flow('demo.ruling', {'actor','skill','amount'}, {
 step('check', function(r, actor, skill) return r.check(actor,skill).passed end,
 {yes='end', no='ruling'}),
 ask('ruling', {role='kp', seconds=60, yes='apply', no='end', timeout='end'}),
 step('apply', function(r, actor, skill, amount) r.damage(actor,amount) end)
})
", E "timed.lua": "return flow('demo.timed', {'actor','amount'}, {
 ask('choice', {role='initiator', seconds=30, yes='apply', no='end', timeout='end'}),
 step('apply', function(r, actor, amount) r.damage(actor,amount) end)
})
", E "transfer-library.lua": "return rule('demo.lib.transfer', {'item','bag','quantity'}, function(r, item, bag, quantity)
 local load = 0
 for _, entry in ipairs(r.items(bag)) do
 load = load + entry.numbers.quantity*entry.numbers.unitMass
 end
 local itemData = r.read(item)
 quantity = quantity or itemData.numbers.quantity
 assert(load + quantity*itemData.numbers.unitMass <= r.number(bag,'capacity'), 'capacity exceeded')
 return r.move(item, bag, quantity)
end, {public=false})
", E "transfer.lua": "return rule('demo.transfer', {'item','bag','quantity'}, function(r, item, bag, quantity)
 return r.transfer(item, bag, quantity)
end)
